// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

interface IAccessControlProbe {
    function hasRole(bytes32 role, address account) external view returns (bool);
}

interface IERC165Probe {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(bytes4 fuzzedId, bool useIERC165Id) public {
        bytes4 probed = useIERC165Id ? type(IERC165Probe).interfaceId : fuzzedId;
        bytes4 accessControlId = type(IAccessControlProbe).interfaceId;

        // General rule: C supports exactly the IERC165 and IAccessControl interfaces.
        // Every non-registered id must return false; both registered ids must return true.
        if (probed != accessControlId && probed != type(IERC165Probe).interfaceId) {
            assertTrue(!c.supportsInterface(probed), "unregistered id must not be supported");
        } else {
            bool ok;
            try c.supportsInterface(probed) returns (bool supported) {
                ok = supported;
            } catch {
                ok = false;
            }
            assertTrue(ok, "registered interface must be supported");
        }
    }
}
